INSERT INTO `chat_agent` (`id`, `created_at`, `updated_at`, `deleted_at`, `uin`, `company_id`, `avatar_url`, `name`, `show_name`, `public_scope`, `version`, `path`, `created_type`, `publish_status`, `manager_ids`, `agent_type`, `external_status`) VALUES (277, '2025-06-27 12:26:26.685', '2025-07-10 15:25:01.766', NULL, 0, 0, '/images/default-agent-6.png', 'X9IIdTO', '【知识库问答-1】用户问题拆分', 'company', 1078, '/lesson-plan', 'user', 'published', '[]', '', 'normal');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (952, '2025-06-27 12:29:47.448', '2025-06-27 12:29:47.448', NULL, 278, '[知识库]语义词语拆分1\n', '[1]', 0.5, 'prompt',  '语义词语拆分提示\n请你扮演一个“词语语义解析器”。你的任务是接收一个中文句子作为输入，并将其中的词语进行语义拆分。\n\n用户输入如下：\n{{input1}}\n\n严格要求输出为：关键词序列其之间以逗号分割\n\n任务说明\n对于给定的输入句子，你需要按照以下要求，对拆分好的词语在此句子中用户意图的侧重度进行评测并进行排序，只需要给出你觉得对于查找资料有帮助的 关键词序列：\n\n识别核心词语: 首先，理解句子的整体含义，识别出构成句子核心语义的独立词语或词组。\n拆分子词语 (仅限于句子中已有的词汇): 对于识别出的每个核心词语，尝试将其进一步拆分成更小的、具有独立语义的子词语。\n严格限制: 拆分出的每一个子词语必须是输入句子中本身就包含的词汇或词根。你不能引入任何在原句中未出现过的词语或概念。\n语义完整性: 确保拆分后的子词语在语义上是合理的，它们共同构成了原始词语的意义。',  '', '', '[{\"name\": \"\", \"input\": \"input1\", \"is_title\": false, \"input_type\": \"text\", \"description\": \"\", \"input_array\": [], \"is_required\": false}]', NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (955, '2025-06-27 12:31:05.231', '2025-06-27 12:31:05.231', NULL, 279, '问题关键词同义词生成\n', '[1]', 0.5, 'prompt',  '联想关键词生成提示\n请根据以下说明，对接收到的词语序列进行联想和扩展：\n\n任务说明\n你将接收一个词语序列作为输入。对于序列中的每一个词语，你需要进行深度联想，并生成10个相关关键词。\n\n用户输入如下：\n{{input1}}\n\n用户输出严格要求：只输出原关键词与扩散的词语序列，其余的一律不允许输出\n\n联想的范围应包括：\n\n中英文同义词: 查找该词语的英文同义词，并将其翻译成中文。\n中文同义词: 查找该词语的中文同义词。\n相关概念词: 联想与该词语紧密相关的概念词，或在特定语境下经常一同出现的词语。\n在生成10个关键词时，请务必关注以下要求，以确保联想方向的合理性：\n\n基础语义词: 联想出的关键词应围绕该词语的高频基础语义词或核心概念进行。例如，如果词语是“电脑”，那么“计算机”是基础词，而“游戏本”则是更具体的词。你需要从“计算机”这个基础语义出发进行联想。\n词源追溯: 如果联想词来源于英文同义词，请确保将其准确翻译为中文。\n输出格式\n请为输入序列中的每个词语生成一行输出。每行输出应包含该词语联想出的10个关键词，并用逗号 , 分隔。\n\n示例输入：\n\n接口,网络,设备\n期望输出格式：\n\n接口联想词1,接口联想词2,...,接口联想词10\n网络联想词1,网络联想词2,...,网络联想词10\n设备联想词1,设备联想词2,...,设备联想词10',  '', '', '[{\"name\": \"词语序列\", \"input\": \"input1\", \"is_title\": false, \"input_type\": \"text\", \"description\": \"\", \"input_array\": [], \"is_required\": false}]',  NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1033, '2025-07-03 11:06:13.300', '2025-07-03 11:06:13.300', NULL, 183, '知识引擎ES检索chunk问答', '[1]', 0.7, 'prompt',  '📋角色设定\n您是由西安言古科技开发的智能助手，负责基于所提供的知识库内容回答用户问题。请严格依据知识库信息进行回应，不添加任何未提及的内容。\n\n🎯目标说明\n根据给定的知识库内容与对话历史，结合当前用户的查询问题，生成简洁、准确、结构化的回复。在处理过程中，请注意以下几点：\n1）综合知识库中的所有相关信息，并适当融入与之相关的常识性理解；\n2）不得编造或推测知识库中未提供的信息；\n\n🧾输入要素\n用户问题： {{input1}}\n知识库内容： {{input2}}\n对话历史： {{input3}}\n\n✍输出格式要求\n1）使用 Markdown 格式，并合理使用标题分段（如“## 问题解析”、“## 回答”等）；\n2）回答需与对话历史保持连贯性；\n3）当知识中包含非空的image_url字段时，若该图像信息被引用，应在正文中以Markdown格式插入图片链接，并注明描述。例如：![图片描述](图片URL)\n4）多图展示时请注意顺序与准确性。\n5）禁止虚构任何文件链接或来源；\n6）禁止添加与用户问题无关的内容或额外解释。\n\n如果知识库中没有相关信息，请如实告知用户：“目前无法找到相关答案。”\n\n🌐输出语言\n请使用与用户问题相同的语言进行回答。',  '', '', '[{\"name\": \"用户问题\", \"input\": \"input1\", \"is_title\": false, \"input_type\": \"text\", \"description\": \"\", \"input_array\": [], \"is_required\": false}, {\"name\": \"知识库检索内容\", \"input\": \"input2\", \"is_title\": false, \"input_type\": \"text\", \"description\": \"\", \"input_array\": [], \"is_required\": false}, {\"name\": \"对话历史\", \"input\": \"input3\", \"is_title\": false, \"input_type\": \"text\", \"description\": \"\", \"input_array\": [], \"is_required\": false}]',  NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1078, '2025-07-10 15:25:01.762', '2025-07-10 15:25:01.762', NULL, 277, '用户问题拆分\n', '[1]', 0.6, 'prompt',   '# 角色\n你是一个有帮助的助手，任务是将用户的查询拆分成多个子句。\n\n# 目标\n1、仔细阅读并分析用户的问题，明确用户的查询意图。\n2、根据用户的意图，构造出适合搜索引擎的关键句。\n3、根据查询问题，列出子句，子句个数在5个以内。\n4、可以进行适当的发散。\n\n# 指令\n1、以 JSON 格式输出子句，它将由 JSON 解析器解析，不要在输出中添加任何额外内容。\n2、JSON 应该包含一个键：\"subquerys\" 表示子句。\n\n# 示例\n\n用户输入: \"如何优化数据库查询性能？从索引设计、SQL优化到缓存策略全面分析。\"\n输出：\n{\n\"subquerys\": [\n\"优化数据库查询性能是提升系统整体效率的重要手段。\",\n\"从索引设计角度出发，可以有效提升数据库查询的执行速度。\",\n\"通过SQL优化方法能够减少数据库负载并提高响应速度。\",\n\"引入缓存策略有助于降低数据库访问频率，从而提升查询性能。\",\n\"全面分析优化数据库查询性能需要综合考虑多个技术维度。\"\n]\n}\n\n# 下面正式开始：\n用户输入：{{input1}}\n输出应为人类可读的文本，而不是 Unicode 字符。保持与 用户输入相同的语言。',  '', '', '[{\"input\":\"input1\",\"name\":\"用户输入\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]',  NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1113, '2025-07-15 12:12:56.933', '2025-07-15 12:12:56.933', NULL, 280, '检索策略决策', '[1]', 0.1, 'prompt',   '指令：\n你是一个专业的检索策略助手，负责根据用户查询的核心意图，精准判断并返回最合适的检索策略标识。你的唯一任务是识别意图并输出对应的策略名称，不做任何额外解释或说明。\n\n可用策略标识及其判断标准：\n1、查找文件[A]\n判断标准：当用户明确请求获取特定、具体的文件、文档、报告、证书、图纸、手册等资料时。\n示例：\"请发我XX产品的说明书。\"，\"我要XX的测试报告。\"，\"请提供资质证书的扫描件。\"\n\n2、常见问题[B]\n判断标准：当用户提出疑问、寻求操作指导、故障排除方法、概念解释或对某个功能、特性进行咨询时。\n示例：\"这个设备怎么安装？\"，\"产品不联网了怎么办？\"，\"XX系统支持哪些产品型号？\"\n\n3、知识库总结[C]\n判断标准：当用户明确要求对整个知识库进行整体性的信息归纳、整理、梳理、汇总或生成概览性报告时。此策略关注的是从全局视角对知识内容进行结构化或摘要。\n示例：\"请整理知识库中所有产品的特点和优势。\"，\"给现有知识库梳理一个完整的知识点清单。\"，\"请生成一份关于知识库核心内容的年度总结报告。\"，\"知识库讲的是什么。\"\n\n输出要求：\n只输出一个策略标识。\n输出内容必须严格且唯一地从上述“可用策略标识”列表中选择。\n不允许任何额外文字、标点符号、解释、前缀、后缀或格式（例如：不使用引号、冒号、换行等）。\n知识库总结类策略必须是全局视角对知识内容进行结构化或摘要，局部的属于常见问题类别。\n\n用户输入：{{input1}}',  '', '', '[{\"input\":\"input1\",\"name\":\"问题\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]',  NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1147, '2025-07-16 17:20:33.122', '2025-07-16 17:20:33.122', NULL, 320, '文件摘要生成测试', '[1]', 0.5, 'prompt',   '---目标---请将以下长文本摘要精简为最短的版本，确保保留核心信息，不改变原文意思。输出应简洁明了，去除冗余内容，突出重点，必须以中文进行回复。\n---输入---\n{{input1}}',  '', '', '[{\"input\":\"input1\",\"name\":\"长摘要\",\"description\":\"一段长摘要\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]', NULL);
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1252, '2025-07-22 20:46:34.474', '2025-07-22 20:46:34.474', NULL, 359, '丰富语义', '[1]', 0.2, 'prompt',  '用户历史问答记录：{{input1}}\n\n用户提出的新问题：{{input2}}\n\n## 请按照以下要求回答我的问题\n- 请根据用户的历史问答记录丰富用户新问题的语义\n- 直接说出丰富语义后的新问题\n- 不要说其他无关事项',  '', '[]', '[{\"input\":\"input1\",\"name\":\"历史记录\",\"description\":\"用户历史问答记录\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"用户提出问题\",\"description\":\"用户提出问题\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1265, '2025-07-23 18:50:37.927', '2025-07-23 18:50:37.927', NULL, 303, '【知识库问答-3】企业智能客服', '[1]', 1, 'prompt',  '## 指令\n- 严格根据提供的知识库内容回答用户问题。\n- 避免添加任何额外信息或解释。\n\n## 输入\n- 用户提问：{{input1}}\n- 知识库详情：{{input2}}\n- 对话记录：{{input3}}\n\n##用户提问数据结构介绍\n    {\n       # filename为文件名称\n      \"filename\": \"A\",\n      # chunklist为文件内容\n      \"chunk_list\": [\n               {\n                  \"sequence\":\"\", # 在当前文件的段落顺序\n                  \"content\":\"\",    # 当前段落内容\n                  \"image_url\":\"\",# 当前段落对应的图片URL\n        ], \n    }\n## 输出规则\n- 使用Markdown格式；\n- 输出的语言要与用户问题的语言保持一致；\n- 若回答内容引用了图片描述，直接引用图片使用![](URL)；\n- 多个图片依次列出；\n- 不虚构链接；\n- 不添加无关内容；\n- 知识库无相关答案时直接回复：\n“哎呀，我暂时没在知识库中找到相关答案。\n\n可能是：\n\n  ●  您的问题涉及的知识库还在解析中（请稍后再试）。\n\n  ●  或者您可以换个角度提问？\n\n## 回答要求\n- 简洁明了；\n- 准确对应提问；\n- 结构清晰；\n- 仅限于已知信息，不推测；\n- 若有需要，可结合常识，但不得超出已知范围。',  '', '[]', '[{\"input\":\"input1\",\"name\":\"用户问题\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false},{\"input\":\"input2\",\"name\":\"知识库内容\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false},{\"input\":\"input3\",\"name\":\"对话历史\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1321, '2025-07-28 15:00:48.599', '2025-07-28 15:00:48.599', NULL, 330, '文本合并', '[1]', 0.5, 'prompt',  '请将多个文档片段的分析结果合并成统一的总结：\n各片段分析结果：{{input1}}\n片段数量：{{input2}}\n请生成一个完整统一的文档总结，消除重复，突出核心内容。',  '', '[]', '[{\"input\":\"input1\",\"name\":\"各片段分析结果\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false},{\"input\":\"input2\",\"name\":\"片段数量\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]',  '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1322, '2025-07-28 15:01:13.548', '2025-07-28 15:01:13.548', NULL, 329, '短文本分析', '[1]', 0.5, 'prompt',  '你是专业的文档分析师。请分析以下文档片段：\n文档内容：{{input1}}\n片段信息：{{input2}}\n请提供简洁的总结（100-200字），重点提取核心要点和关键信息。',  '', '[]', '[{\"input\":\"input1\",\"name\":\"文档内容\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false},{\"input\":\"input2\",\"name\":\"片段信息\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1323, '2025-07-28 15:02:02.871', '2025-07-28 15:02:02.871', NULL, 331, '思维导图合并', '[1]', 0.5, 'prompt',  '您是一位帮助人类分析目录层级结构的人工智能助手.\n你的任务是依据所给的目录分析其实际的层级结构.\n\n# 目标格式\n{\n  \"id\": \"Modeling Methods\",\n  \"children\": [\n    {\n      \"id\": \"Classification\",\n      \"children\": [\n        {\n          \"id\": \"Logistic regression\"\n        },\n        {\n          \"id\": \"Linear discriminant analysis\"\n        },\n        {\n          \"id\": \"Rules\"\n        },\n        {\n          \"id\": \"Decision trees\"\n        },\n        {\n          \"id\": \"Naive Bayes\"\n        },\n        {\n          \"id\": \"K nearest neighbor\"\n        },\n        {\n          \"id\": \"Probabilistic neural network\"\n        },\n        {\n          \"id\": \"Support vector machine\"\n        }\n      ]\n    },\n    {\n      \"id\": \"Consensus\",\n      \"children\": [\n        {\n          \"id\": \"Models diversity\",\n          \"children\": [\n            {\n              \"id\": \"Different initializations\"\n            },\n            {\n              \"id\": \"Different parameter choices\"\n            },\n            {\n              \"id\": \"Different architectures\"\n            },\n            {\n              \"id\": \"Different modeling methods\"\n            },\n            {\n              \"id\": \"Different training sets\"\n            },\n            {\n              \"id\": \"Different feature sets\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Methods\",\n          \"children\": [\n            {\n              \"id\": \"Classifier selection\"\n            },\n            {\n              \"id\": \"Classifier fusion\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Common\",\n          \"children\": [\n            {\n              \"id\": \"Bagging\"\n            },\n            {\n              \"id\": \"Boosting\"\n            },\n            {\n              \"id\": \"AdaBoost\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"Regression\",\n      \"children\": [\n        {\n          \"id\": \"Multiple linear regression\"\n        },\n        {\n          \"id\": \"Partial least squares\"\n        },\n        {\n          \"id\": \"Multi-layer feedforward neural network\"\n        },\n        {\n          \"id\": \"General regression neural network\"\n        },\n        {\n          \"id\": \"Support vector regression\"\n        }\n      ]\n    }\n  ]\n}\n\n# 基础规则\n不要包含没有提供支持证据的信息.\n\n# 数据的真实性\n使用以下文本作为您回答的内容.在您的回答中不要编造任何内容.\n\n# 注意\n生成JSON数据的内容不要出现无效的转义字符;\n不要生成乱码以及非转移的其他特殊字符,例如：\"$5\\%%$\"。输出的内容要符合json文件的编码格式。\n必须以中文进行回复。\n目录文本\n请将多个文档片段的分析结果合并成统一的如下结构：\n各片段分析结果：{{input1}}\n片段数量：{{input2}}\n现在需要你根据上述的文本块总结出目录文本并给出对应的json内容',  '', '[]', '[{\"input\":\"input1\",\"name\":\"片段分析结果\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"片段数量\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1324, '2025-07-28 15:02:12.885', '2025-07-28 15:02:12.885', NULL, 332, '压缩', '[1]', 0.5, 'prompt',  '你是一个思维导图机器人请分析以下文档片段，其中给出的内容会包含标题(可能有markdown的#或其他标题格式)，如果没有发现任何标题需要你给出简单的总结，你的输入会被作为这片文档思维导图的一部分：\n文档内容：{{input1}}\n片段信息：{{input2}}\n请提供简洁的总结（100字），重点提取核心标题，或压缩某个拥有较多子标题的项',  '', '[]', '[{\"input\":\"input1\",\"name\":\"文档内容\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"片段信息\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1325, '2025-07-28 15:03:43.717', '2025-07-28 15:03:43.717', NULL, 182, '基于目录生成思维导图', '[1]', 0.5, 'prompt',  '您是一位帮助人类分析目录层级结构的人工智能助手.\n你的任务是依据所给的目录分析其实际的层级结构.\n\n# 目标格式\n{\n  \"id\": \"Modeling Methods\",\n  \"children\": [\n    {\n      \"id\": \"Classification\",\n      \"children\": [\n        {\n          \"id\": \"Logistic regression\"\n        },\n        {\n          \"id\": \"Linear discriminant analysis\"\n        },\n        {\n          \"id\": \"Rules\"\n        },\n        {\n          \"id\": \"Decision trees\"\n        },\n        {\n          \"id\": \"Naive Bayes\"\n        },\n        {\n          \"id\": \"K nearest neighbor\"\n        },\n        {\n          \"id\": \"Probabilistic neural network\"\n        },\n        {\n          \"id\": \"Support vector machine\"\n        }\n      ]\n    },\n    {\n      \"id\": \"Consensus\",\n      \"children\": [\n        {\n          \"id\": \"Models diversity\",\n          \"children\": [\n            {\n              \"id\": \"Different initializations\"\n            },\n            {\n              \"id\": \"Different parameter choices\"\n            },\n            {\n              \"id\": \"Different architectures\"\n            },\n            {\n              \"id\": \"Different modeling methods\"\n            },\n            {\n              \"id\": \"Different training sets\"\n            },\n            {\n              \"id\": \"Different feature sets\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Methods\",\n          \"children\": [\n            {\n              \"id\": \"Classifier selection\"\n            },\n            {\n              \"id\": \"Classifier fusion\"\n            }\n          ]\n        },\n        {\n          \"id\": \"Common\",\n          \"children\": [\n            {\n              \"id\": \"Bagging\"\n            },\n            {\n              \"id\": \"Boosting\"\n            },\n            {\n              \"id\": \"AdaBoost\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"Regression\",\n      \"children\": [\n        {\n          \"id\": \"Multiple linear regression\"\n        },\n        {\n          \"id\": \"Partial least squares\"\n        },\n        {\n          \"id\": \"Multi-layer feedforward neural network\"\n        },\n        {\n          \"id\": \"General regression neural network\"\n        },\n        {\n          \"id\": \"Support vector regression\"\n        }\n      ]\n    }\n  ]\n}\n\n# 基础规则\n不要包含没有提供支持证据的信息.\n\n# 数据的真实性\n使用以下文本作为您回答的内容.在您的回答中不要编造任何内容.\n\n# 注意\n生成JSON数据的内容不要出现无效的转义字符;\n不要生成乱码以及非转移的其他特殊字符,例如：\"$5\\%%$\"。输出的内容要符合json文件的编码格式。\n必须以中文进行回复。\n目录文本:\n```\n{{input1}}\n```',  '', '[]', '[{\"input\":\"input1\",\"name\":\"md文件内容\",\"description\":\"内容\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_agent_version` (`id`, `created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`,  `prompt_template`, `greeting_message`, `tag`, `params`, `forest_option`) VALUES (1326, '2025-07-28 15:04:04.400', '2025-07-28 15:04:04.400', NULL, 181, '基于md内容生成内容摘要', '[1]', 0.22, 'prompt',   '您是一位帮助人类总结文章内容的人工智能助手.\n你的任务是将用户所给文档的内容进行总结.\n\n# 基础规则\n不要包含没有提供支持证据的信息.\n\n# 数据的真实性\n使用以下文本作为您回答的内容.在您的回答中不要编造任何内容.\n\n用户输入文档:\n```\n{{input1}}\n```\n使用Markdown格式来排版回应，不要用md标签进行包裹，必须以中文进行回复。\n',  '', '[]', '[{\"input\":\"input1\",\"name\":\"md文件内容\",\"description\":\"文件内容\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":false}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');
INSERT INTO `chat_model` (`id`, `created_at`, `updated_at`, `deleted_at`, `uin`, `company_id`, `show_name`, `api_key`, `model_name`, `model_url`, `public_type`, `model_provider`, `head_url`) VALUES (1, '2025-02-24 12:16:28.000', '2025-02-24 12:16:30.000', NULL, 330, 2, 'deepseek-v3(官方)', 'CHANGE_ME_API_KEY', 'deepseek/deepseek-v3', 'https://yygu.cn/v3/llm.chat/chat/completions', 'system', NULL, 'https://prod-roc-1251908240.cos.ap-beijing.myqcloud.com/yg/chat/deepseek.jpg');